#include <sstream>
#include <string>
#include <vector>
using namespace std;

class Item {
public:
    Item(int id, const string& name) : id(id), name(name) {}
    virtual ~Item() = default;
    virtual string kind() const { return "东西"; }
    virtual int keepDays() const { return 7; }
    int id;
    string name;
    bool out = false;
};

class Book : public Item {
public:
    Book(int id, const string& name) : Item(id, name) {}
